import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Search } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { KEYS, asyncGet, apiPost } from '../services/storage';
import { getGroups } from '../services/participantGroups';
import { fetchProjectMembers } from '../services/projectApi';
import { createBulkNotifications } from '../services/notifications';
import { Button, Input, Select, Textarea, Avatar } from '../components/ui';
import toast from 'react-hot-toast';
import { v4 as uuidv4 } from 'uuid';

export default function NewMeeting() {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [users, setUsers] = useState([]);
  const [projects, setProjects] = useState([]);
  const [myGroups, setMyGroups] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [projectMemberIds, setProjectMemberIds] = useState([]);
  const [minDate, setMinDate] = useState('');
  const [currentOnlineTime, setCurrentOnlineTime] = useState('');
  const initialProjectId = searchParams.get('projectId') || '';
  const [form, setForm] = useState({
    title: '', agenda: '', date: '', time: '', duration: '60',
    type: initialProjectId ? 'project' : 'general', standupType: 'morning', participantIds: [],
    projectId: initialProjectId
  });

  useEffect(() => {
    (async () => {
      setUsers(await asyncGet(KEYS.USERS) || []);
      setProjects(await asyncGet(KEYS.PROJECTS) || []);

      try {
        const fetchedGroups = await getGroups(currentUser.id);
        setMyGroups(fetchedGroups || []);
      } catch (err) {
        console.error("Failed to fetch groups", err);
      }

      try {
        const res = await fetch('https://worldtimeapi.org/api/timezone/Etc/UTC');
        if (res.ok) {
          const data = await res.json();
          const onlineDate = new Date(data.datetime);
          const localYear = onlineDate.getFullYear();
          const localMonth = String(onlineDate.getMonth() + 1).padStart(2, '0');
          const localDay = String(onlineDate.getDate()).padStart(2, '0');
          const localHours = String(onlineDate.getHours()).padStart(2, '0');
          const localMinutes = String(onlineDate.getMinutes()).padStart(2, '0');

          setMinDate(`${localYear}-${localMonth}-${localDay}`);
          setCurrentOnlineTime(`${localHours}:${localMinutes}`);
        } else {
          throw new Error('API request failed');
        }
      } catch (err) {
        console.warn("Failed to fetch online time, falling back to system time");
        const now = new Date();
        const localYear = now.getFullYear();
        const localMonth = String(now.getMonth() + 1).padStart(2, '0');
        const localDay = String(now.getDate()).padStart(2, '0');
        const localHours = String(now.getHours()).padStart(2, '0');
        const localMinutes = String(now.getMinutes()).padStart(2, '0');

        setMinDate(`${localYear}-${localMonth}-${localDay}`);
        setCurrentOnlineTime(`${localHours}:${localMinutes}`);
      }

      // Auto-include current user
      setForm(f => ({ ...f, participantIds: [currentUser.id] }));

      if (initialProjectId) {
        await fetchAndAddProjectMembers(initialProjectId);
      }
    })();
  }, [currentUser.id]);

  const fetchAndAddProjectMembers = async (projectId, isSwitching = false) => {
    if (!projectId) {
      if (isSwitching) {
        setForm(f => ({
          ...f,
          participantIds: f.participantIds.filter(id => !projectMemberIds.includes(String(id)))
        }));
        setProjectMemberIds([]);
      }
      return;
    }
    try {
      const members = await fetchProjectMembers(projectId);
      if (members && members.length > 0) {
        const newIds = members.map(m => String(m.userId));
        setForm(f => {
          let currentIds = f.participantIds.map(String);
          if (isSwitching) {
            currentIds = currentIds.filter(id => !projectMemberIds.includes(id));
          }
          const updatedIds = [...new Set([...currentIds, ...newIds, String(currentUser.id)])];
          return { ...f, participantIds: updatedIds };
        });
        setProjectMemberIds(newIds);
        toast.success(`Auto-selected ${members.length} project member(s)`);
      }
    } catch (err) {
      console.error("Failed to fetch project members for auto-select", err);
    }
  };

  const applyGroup = (groupId) => {
    if (!groupId) return;
    const group = myGroups.find(g => g.id === Number(groupId));
    if (group && group.participantIds) {
      setForm(f => {
        // Merge without duplicates, normalizing to Numbers
        const currentIds = f.participantIds.map(Number);
        const newIds = group.participantIds.map(Number);
        const updatedIds = [...new Set([...currentIds, ...newIds])];
        return { ...f, participantIds: updatedIds };
      });
      toast.success(`Added members of ${group.name}`);
    }
  };

  const handleProjectChange = async (projectId) => {
    setForm(f => ({ ...f, projectId }));
    await fetchAndAddProjectMembers(projectId, true);
  };

  const handleTypeChange = async (type) => {
    setForm(f => ({ ...f, type }));
    if (type === 'project' && form.projectId) {
      await fetchAndAddProjectMembers(form.projectId, true);
    }
  };

  const toggleParticipant = (uid) => {
    const stringUid = String(uid);
    setForm(f => {
      const isSelected = f.participantIds.some(id => String(id) === stringUid);
      return {
        ...f,
        participantIds: isSelected
          ? f.participantIds.filter(id => String(id) !== stringUid)
          : [...f.participantIds, stringUid]
      };
    });
  };

  const handleSubmit = async () => {
    if (!form.title || !form.agenda || !form.date || !form.time) { toast.error('Please fill in all required fields'); return; }

    if (form.date === minDate && form.time < currentOnlineTime) {
      toast.error('Cannot schedule a meeting in the past');
      return;
    }

    setLoading(true);
    await new Promise(r => setTimeout(r, 300));

    const meetingId = uuidv4();
    const meeting = {
      id: meetingId,
      ...form,
      hostId: currentUser.id,
      status: 'upcoming',
      createdAt: new Date().toISOString(),
    };

    await apiPost(KEYS.MEETINGS, meeting);

    // Notify all participants (except host)
    const others = form.participantIds.filter(id => id !== currentUser.id);
    createBulkNotifications(others, {
      type: 'meeting_invited',
      title: 'Meeting Invitation',
      message: `You've been invited to "${form.title}" on ${form.date} at ${form.time}`,
      relatedId: meetingId,
      relatedType: 'meeting'
    });

    toast.success('Meeting scheduled!');
    navigate(`/meetings/${meetingId}`);
    setLoading(false);
  };

  const activeUsers = users.filter(u => u.isActive && u.isApproved);
  const filteredUsers = activeUsers.filter(u =>
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (u.role && u.role.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div className="max-w-3xl mx-auto space-y-6 animate-fade-in">
      <div>
        <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-500 hover:text-gray-300 text-sm mb-4 transition-colors">
          <ArrowLeft size={16} />Back
        </button>
        <h1 className="text-2xl font-bold text-gray-100">Schedule Meeting</h1>
      </div>

      <div className="card p-6 space-y-4">
        <Input label="Meeting Title *" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
        <Textarea label="Agenda *" value={form.agenda} onChange={e => setForm({ ...form, agenda: e.target.value })} />

        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          <Input
            label="Date *"
            type="date"
            min={minDate}
            value={form.date}
            onChange={e => {
              const newDate = e.target.value;
              let newTime = form.time;
              if (newDate === minDate && newTime && newTime < currentOnlineTime) {
                newTime = currentOnlineTime;
                toast.error("Time adjusted to minimum valid time for today.");
              }
              setForm({ ...form, date: newDate, time: newTime });
            }}
          />
          <Input
            label="Time *"
            type="time"
            min={form.date === minDate ? currentOnlineTime : undefined}
            value={form.time}
            onChange={e => {
              let newTime = e.target.value;
              if (form.date === minDate && newTime < currentOnlineTime) {
                toast.error("Cannot select a past time for today.");
                newTime = currentOnlineTime;
              }
              setForm({ ...form, time: newTime });
            }}
          />
          <Select label="Duration" value={form.duration} onChange={e => setForm({ ...form, duration: e.target.value })}>
            <option value="15">15 minutes</option>
            <option value="30">30 minutes</option>
            <option value="60">1 hour</option>
            <option value="90">1.5 hours</option>
            <option value="120">2 hours</option>
          </Select>
          <Select label="Meeting Type" value={form.type} onChange={e => handleTypeChange(e.target.value)}>
            <option value="standup">Daily Standup</option>
            <option value="project">Project Discussion</option>
            <option value="general">General</option>
          </Select>
          {form.type === 'project' && projects.length > 0 && (
            <Select label="Link to Project" value={form.projectId} onChange={e => handleProjectChange(e.target.value)}>
              <option value="">No project</option>
              {projects.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
            </Select>
          )}
        </div>

        {form.type === 'standup' && (
          <div className="p-4 bg-gray-800/50 rounded-xl">
            <label className="label mb-3">Standup Type</label>
            <div className="flex gap-6">
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="radio" checked={form.standupType === 'morning'} onChange={() => setForm({ ...form, standupType: 'morning' })} className="text-primary-600" />
                <span className="text-sm text-gray-300">Morning (What will you do today?)</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="radio" checked={form.standupType === 'evening'} onChange={() => setForm({ ...form, standupType: 'evening' })} className="text-primary-600" />
                <span className="text-sm text-gray-300">Evening (What did you do today?)</span>
              </label>
            </div>
          </div>
        )}



        {/* Participants */}
        <div>
          <div className="flex flex-col md:flex-row md:items-center justify-between mb-3 gap-2">
            <label className="label">Participants</label>
            <div className="flex flex-col sm:flex-row gap-2">
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search participants..."
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="input-field text-sm pl-9 w-full sm:w-64"
                />
              </div>
              {myGroups.length > 0 && (
                <select
                  className="input-field text-sm w-full sm:w-64"
                  onChange={(e) => applyGroup(e.target.value)}
                  defaultValue=""
                >
                  <option value="" disabled>Apply a Group...</option>
                  {myGroups.map(g => (
                    <option key={g.id} value={g.id}>{g.name} ({g.participantIds?.length || 0})</option>
                  ))}
                </select>
              )}
            </div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2 max-h-64 overflow-y-auto custom-scrollbar pr-2">
            {filteredUsers.length === 0 ? (
              <div className="col-span-2 md:col-span-3 text-center py-8 text-gray-500 bg-gray-800/30 rounded-xl border border-dashed border-gray-700">
                <p>No participants found matching "{searchTerm}"</p>
              </div>
            ) : (
              filteredUsers.map(u => {
                const isSelected = form.participantIds.some(id => String(id) === String(u.id));
                return (
                  <label key={u.id} className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors ${isSelected ? 'bg-primary-900/30 border border-primary-800/50' : 'hover:bg-gray-800 border border-transparent'}`}>
                    <input type="checkbox" checked={isSelected} onChange={() => toggleParticipant(u.id)} className="rounded border-gray-600 bg-gray-700 text-primary-600" disabled={u.id === currentUser.id} />
                    <Avatar name={u.name} size="xs" />
                    <div>
                      <p className="text-xs font-medium text-gray-200">{u.name}</p>
                      <p className="text-xs text-gray-500 capitalize">{u.role}</p>
                    </div>
                  </label>
                );
              })
            )}
          </div>
          <p className="text-xs text-gray-500 mt-2">{form.participantIds.length} participant(s) selected</p>
        </div>

        <div className="flex justify-end gap-3 pt-4 border-t border-gray-800">
          <Button variant="secondary" onClick={() => navigate(-1)}>Cancel</Button>
          <Button loading={loading} onClick={handleSubmit}>Schedule Meeting</Button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
   
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, Trash } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { KEYS, asyncGet, apiPost } from '../services/storage';
import { createBulkNotifications } from '../services/notifications';
import { createProject, addProjectMember } from '../services/projectApi';
import { Button, Input, Select, Textarea, TagInput } from '../components/ui';
import toast from 'react-hot-toast';
import { v4 as uuidv4 } from 'uuid';

const CATEGORIES = ['Web', 'Mobile', 'Internal', 'R&D', 'Other'];
const PRIORITIES = ['low', 'medium', 'high', 'critical'];
const STATUSES = ['planning', 'active'];

export default function NewProject() {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    title: '', description: '', clientName: '', category: 'Web', priority: 'medium', status: 'planning',
    startDate: '', endDate: '', deadline: '', gitRepo: '', technologies: [], tags: [],
    ownerId: '', managerId: '', teamIds: [] });
  const [milestones, setMilestones] = useState([{ title: '', description: '', targetDate: '' }]);

  useEffect(() => {
    (async () => {
    const us = await asyncGet(KEYS.USERS) || [];
    setUsers(us.filter(u => u.isActive && u.isApproved));
    // Default owner to self if employee
    if (['employee', 'manager'].includes(currentUser.role)) {
      setForm(f => ({ ...f, ownerId: currentUser.id }));
    }
  })();
   
  }, []);

  const addMilestone = () => setMilestones([...milestones, { title: '', description: '', targetDate: '' }]);
  const removeMilestone = (idx) => setMilestones(milestones.filter((_, i) => i !== idx));
  const updateMilestone = (idx, field, value) => {
    const ms = [...milestones];
    ms[idx] = { ...ms[idx], [field]: value };
    setMilestones(ms);
  };

  const toggleTeamMember = (uid) => {
    setForm(f => ({ ...f, teamIds: f.teamIds.includes(uid) ? f.teamIds.filter(id => id !== uid) : [...f.teamIds, uid] }));
  };

  const handleSubmit = async () => {
    if (!form.title || !form.startDate || !form.endDate) { toast.error('Title, start date and end date are required'); return; }
    
    const todayStr = new Date().toISOString().split('T')[0];
    if (form.startDate < todayStr) { toast.error('Start date cannot be in the past'); return; }
    if (form.endDate < todayStr) { toast.error('End date cannot be in the past'); return; }
    if (form.startDate > form.endDate) { toast.error('End date must be on or after start date'); return; }
    if (form.deadline && form.deadline < form.startDate) { toast.error('Deadline cannot be before start date'); return; }

    for (let i = 0; i < milestones.length; i++) {
      const ms = milestones[i];
      if (ms.title && ms.targetDate) {
        if (ms.targetDate < form.startDate) {
          toast.error(`Milestone "${ms.title}" target date cannot be before project start date`);
          return;
        }
        if (ms.targetDate > form.endDate) {
          toast.error(`Milestone "${ms.title}" target date cannot be after project end date`);
          return;
        }
      }
    }

    setLoading(true);
    await new Promise(r => setTimeout(r, 300));

    const teamIds = [...new Set([...(form.teamIds), form.ownerId, form.managerId].filter(Boolean))];

    const project = {
      title: form.title,
      description: form.description,
      clientName: form.clientName,
      category: form.category,
      priority: form.priority,
      status: form.status,
      ownerId: form.ownerId ? Number(form.ownerId) : null,
      managerId: form.managerId ? Number(form.managerId) : null,
      startDate: form.startDate,
      endDate: form.endDate,
      deadline: form.deadline,
      gitRepo: form.gitRepo,
      progress: 0,
      createdAt: new Date().toISOString(),
    };

    const createdProject = await createProject(project);
    const projectId = String(createdProject.id);
    
    // Create team members
    for (const uid of teamIds) {
      await addProjectMember(projectId, uid, false);
    }

    // Create milestones
    await Promise.all(
      milestones.filter(m => m.title).map((m, idx) =>
        apiPost(KEYS.MILESTONES, {
          id: uuidv4(), projectId,
          title: m.title, description: m.description, targetDate: m.targetDate,
          actualDate: null, status: idx === 0 ? 'active' : 'upcoming',
          isLocked: idx === 0, delayDays: 0, delayReason: '', delayedAt: null,
          rescheduledDate: null, completionPct: 0, milestoneOrder: idx + 1,
        })
      )
    );

    // Create initial requirement
    await apiPost(KEYS.PROJECT_REQUIREMENTS, {
      id: uuidv4(), projectId, version: '1.0', title: 'Initial Requirements',
      description: '', addedBy: currentUser.id, addedAt: new Date().toISOString(),
      type: 'initial', clientChangeNote: '',
    });

    // Log history
    await apiPost(KEYS.PROJECT_HISTORY, {
      id: uuidv4(), projectId, action: 'project_created',
      performedBy: currentUser.id, targetId: projectId, targetType: 'project',
      details: `Project "${form.title}" created`, timestamp: new Date().toISOString(),
    });

    // Notify team
    createBulkNotifications(teamIds, {
      type: 'project_added', title: 'Added to Project',
      message: `You've been added to the "${form.title}" project`,
      relatedId: projectId, relatedType: 'project',
    });

    toast.success('Project created successfully!');
    navigate(`/projects/${projectId}`);
    setLoading(false);
  };

  const eligibleOwners = users.filter(u => ['employee', 'manager'].includes(u.role));
  const eligibleManagers = users.filter(u => u.role === 'manager');

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fade-in">
      <div>
        <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-500 hover:text-gray-300 text-sm mb-4 transition-colors">
          <ArrowLeft size={16} />Back
        </button>
        <h1 className="text-2xl font-bold text-gray-100">Create New Project</h1>
      </div>

      {/* Section 1: Basic Info */}
      <div className="card p-6">
        <h2 className="font-semibold text-gray-100 mb-4 flex items-center gap-2"><span className="w-6 h-6 bg-primary-600 rounded-full text-white text-xs flex items-center justify-center">1</span>Basic Information</h2>
        <div className="space-y-4">
          <Input label="Project Name *" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
          <Textarea label="Description *" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} />
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            <Input label="Client Name" value={form.clientName} onChange={e => setForm({ ...form, clientName: e.target.value })} />
            <Select label="Category" value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </Select>
            <Select label="Priority" value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })}>
              {PRIORITIES.map(p => <option key={p} value={p} className="capitalize">{p}</option>)}
            </Select>
            <Select label="Status" value={form.status} onChange={e => setForm({ ...form, status: e.target.value })}>
              {STATUSES.map(s => <option key={s} value={s} className="capitalize">{s}</option>)}
            </Select>
            <Input 
              label="Start Date *" 
              type="date" 
              value={form.startDate} 
              min={new Date().toISOString().split('T')[0]}
              onChange={e => setForm({ ...form, startDate: e.target.value })} 
            />
            <Input 
              label="End Date *" 
              type="date" 
              value={form.endDate} 
              min={form.startDate || new Date().toISOString().split('T')[0]}
              onChange={e => setForm({ ...form, endDate: e.target.value })} 
            />
            <Input 
              label="Hard Deadline" 
              type="date" 
              value={form.deadline} 
              min={form.startDate || new Date().toISOString().split('T')[0]}
              onChange={e => setForm({ ...form, deadline: e.target.value })} 
            />
            <Input label="Git Repo Link" type="url" placeholder="https://github.com/..." value={form.gitRepo} onChange={e => setForm({ ...form, gitRepo: e.target.value })} />
          </div>
          <TagInput label="Technology Stack" tags={form.technologies} onChange={techs => setForm({ ...form, technologies: techs })} placeholder="Add technology..." />
          <TagInput label="Tags" tags={form.tags} onChange={tags => setForm({ ...form, tags })} placeholder="Add tag..." />
        </div>
      </div>

      {/* Section 2: Team */}
      <div className="card p-6">
        <h2 className="font-semibold text-gray-100 mb-4 flex items-center gap-2"><span className="w-6 h-6 bg-primary-600 rounded-full text-white text-xs flex items-center justify-center">2</span>Team</h2>
        <div className="grid grid-cols-2 gap-4 mb-4">
          <Select label="Project Owner" value={form.ownerId} onChange={e => setForm({ ...form, ownerId: e.target.value })}>
            <option value="">Select owner</option>
            {eligibleOwners.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
          </Select>
          <Select label="Project Manager" value={form.managerId} onChange={e => setForm({ ...form, managerId: e.target.value })}>
            <option value="">Select manager (optional)</option>
            {eligibleManagers.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
          </Select>
        </div>
        <div>
          <label className="label">Team Members</label>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            {users.filter(u => ['employee', 'intern', 'manager'].includes(u.role)).map(u => (
              <label key={u.id} className="flex items-center gap-2 p-2 hover:bg-gray-800 rounded-lg cursor-pointer">
                <input type="checkbox" checked={form.teamIds.includes(u.id)} onChange={() => toggleTeamMember(u.id)} className="rounded border-gray-600 bg-gray-700 text-primary-600" />
                <span className="text-sm text-gray-300">{u.name}</span>
                <span className="text-xs text-gray-600 capitalize">{u.role}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Section 3: Milestones */}
      <div className="card p-6">
        <h2 className="font-semibold text-gray-100 mb-4 flex items-center gap-2"><span className="w-6 h-6 bg-primary-600 rounded-full text-white text-xs flex items-center justify-center">3</span>Milestones</h2>
        <div className="space-y-4">
          {milestones.map((ms, idx) => (
            <div key={idx} className="p-4 bg-gray-800/50 border border-gray-700 rounded-xl">
              <div className="flex items-center justify-between mb-3">
                <span className="text-sm font-medium text-gray-400">Milestone {idx + 1}</span>
                {milestones.length > 1 && <button onClick={() => removeMilestone(idx)} className="text-gray-600 hover:text-red-400 transition-colors"><Trash size={14} /></button>}
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <div className="md:col-span-2">
                  <Input label="Title *" value={ms.title} onChange={e => updateMilestone(idx, 'title', e.target.value)} />
                </div>
                <Input 
                  label="Target Date" 
                  type="date" 
                  value={ms.targetDate} 
                  min={form.startDate || new Date().toISOString().split('T')[0]}
                  onChange={e => updateMilestone(idx, 'targetDate', e.target.value)} 
                />
                <div className="md:col-span-3">
                  <Textarea label="Description" value={ms.description} onChange={e => updateMilestone(idx, 'description', e.target.value)} />
                </div>
              </div>
            </div>
          ))}
          <Button variant="secondary" onClick={addMilestone}><Plus size={14} />Add Milestone</Button>
        </div>
      </div>

      {/* Submit */}
      <div className="flex justify-end gap-3">
        <Button variant="secondary" onClick={() => navigate(-1)}>Cancel</Button>
        <Button loading={loading} onClick={handleSubmit}><Plus size={14} />Create Project</Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
   
import { CheckCircle, XCircle, AlertTriangle } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { createNotification } from '../services/notifications';
import { Avatar, Button, Modal, Skeleton } from '../components/ui';
import { formatRelativeTime } from '../utils/dates';
import toast from 'react-hot-toast';
import api from '../services/api';

export default function PendingApprovals() {
  const { currentUser } = useAuth();
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [rejectModal, setRejectModal] = useState(null);
  const [rejectReason, setRejectReason] = useState('');

  const load = async () => {
    try {
      const [reqsResp, usersResp] = await Promise.all([
        api.get('/registrationRequests'),
        api.get('/users')
      ]);
      const reqs = reqsResp.data || [];
      const users = usersResp.data || [];
      const enriched = reqs.map(r => ({ ...r, user: users.find(u => String(u.id) === String(r.userId)) })).filter(r => r.user);
      setRequests(enriched);
    } catch (error) {
      console.error('Error loading pending approvals:', error);
      toast.error('Failed to load pending approvals');
    } finally {
      setLoading(false);
    }
  };

   
  useEffect(() => { load(); }, []);

  const handleApprove = async (req) => {
    try {
      // Fetch the user from backend and update via PUT
      const userResp = await api.get(`/users/${req.userId}`);
      const user = userResp.data;
      const updatedUser = {
        ...user,
        isApproved: true,
        isActive: true,
        approvedBy: currentUser.id,
        approvedAt: new Date().toISOString(),
      };
      await api.put(`/users/${req.userId}`, updatedUser);

      // Update registration request status via PUT
      const updatedReq = {
        ...req,
        user: undefined, // remove enriched field before sending
        status: 'approved',
        reviewedBy: currentUser.id,
        reviewedAt: new Date().toISOString(),
      };
      delete updatedReq.user;
      await api.put(`/registrationRequests/${req.id}`, updatedReq);

      createNotification({
        userId: req.userId,
        type: 'registration_approved',
        title: 'Account Approved!',
        message: 'Your registration has been approved. You can now log in to SetTribe.',
        relatedType: 'user',
      });
      toast.success(`${req.user?.name}'s account approved!`);
      load();
    } catch (e) {
      console.error('Approve error:', e);
      toast.error('Failed to approve. Please try again.');
    }
  };

  const handleReject = async () => {
    if (!rejectReason.trim()) { toast.error('Please provide a rejection reason'); return; }
    const req = rejectModal;
    try {
      const updatedReq = {
        id: req.id,
        userId: req.userId,
        status: 'rejected',
        requestedAt: req.requestedAt,
        rejectionReason: rejectReason,
        reviewedBy: currentUser.id,
        reviewedAt: new Date().toISOString(),
      };
      await api.put(`/registrationRequests/${req.id}`, updatedReq);

      createNotification({
        userId: req.userId,
        type: 'registration_rejected',
        title: 'Account Not Approved',
        message: `Your registration was not approved. Reason: ${rejectReason}`,
        relatedType: 'user',
      });
      toast.success('Registration rejected');
      setRejectModal(null);
      setRejectReason('');
      load();
    } catch (e) {
      console.error('Reject error:', e);
      toast.error('Failed to reject. Please try again.');
    }
  };

  const pending = requests.filter(r => r.status === 'pending');
  const reviewed = requests.filter(r => r.status !== 'pending');

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h1 className="text-2xl font-bold text-gray-100">Pending Approvals</h1>
        <p className="text-sm text-gray-500 mt-1">{pending.length} pending registration requests</p>
      </div>

      {loading ? (
        <div className="space-y-3">{Array(3).fill(0).map((_, i) => <Skeleton key={i} className="h-24" />)}</div>
      ) : pending.length === 0 ? (
        <div className="card p-12 text-center">
          <CheckCircle size={40} className="text-emerald-500 mx-auto mb-3" />
          <h2 className="font-semibold text-gray-200">All caught up!</h2>
          <p className="text-sm text-gray-500 mt-1">No pending registration requests</p>
        </div>
      ) : (
        <div className="card overflow-hidden">
          <div className="p-4 border-b border-gray-800">
            <h2 className="font-semibold text-gray-100 flex items-center gap-2"><AlertTriangle size={16} className="text-yellow-400" /> Pending Requests</h2>
          </div>
          <table className="w-full">
            <thead className="border-b border-gray-800">
              <tr className="text-left text-xs text-gray-500 uppercase">
                <th className="px-4 py-3">Applicant</th>
                <th className="px-4 py-3">Role</th>
                <th className="px-4 py-3">Department</th>
                <th className="px-4 py-3">Submitted</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-800">
              {pending.map(req => (
                <tr key={req.id} className="hover:bg-gray-800/30">
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-3">
                      <Avatar name={req.user?.name} size="sm" />
                      <div>
                        <p className="text-sm font-medium text-gray-200">{req.user?.name}</p>
                        <p className="text-xs text-gray-500">{req.user?.email}</p>
                        <p className="text-xs text-gray-600 font-mono">{req.user?.employeeId}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-4 text-sm text-gray-400 capitalize">{req.user?.role}</td>
                  <td className="px-4 py-4 text-sm text-gray-400">{req.user?.department}</td>
                  <td className="px-4 py-4 text-xs text-gray-500">{formatRelativeTime(req.requestedAt)}</td>
                  <td className="px-4 py-4">
                    <div className="flex gap-2">
                      <Button variant="success" size="sm" onClick={() => handleApprove(req)}><CheckCircle size={12} /> Approve</Button>
                      <Button variant="danger" size="sm" onClick={() => setRejectModal(req)}><XCircle size={12} /> Reject</Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Recently Reviewed */}
      {reviewed.length > 0 && (
        <div className="card overflow-hidden">
          <div className="p-4 border-b border-gray-800">
            <h2 className="font-semibold text-gray-100">Recently Reviewed</h2>
          </div>
          <div className="divide-y divide-gray-800">
            {reviewed.slice(0, 10).map(req => (
              <div key={req.id} className="flex items-center gap-4 px-4 py-3">
                <Avatar name={req.user?.name} size="sm" />
                <div className="flex-1">
                  <p className="text-sm text-gray-300">{req.user?.name} <span className="text-gray-500">— {req.user?.role}</span></p>
                  {req.status === 'rejected' && req.rejectionReason && <p className="text-xs text-red-400 mt-0.5">Reason: {req.rejectionReason}</p>}
                </div>
                <span className={`badge ${req.status === 'approved' ? 'bg-emerald-900/40 text-emerald-400 border border-emerald-800/50' : 'bg-red-900/40 text-red-400 border border-red-800/50'}`}>
                  {req.status}
                </span>
                <span className="text-xs text-gray-600">{formatRelativeTime(req.reviewedAt)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Reject Modal */}
      <Modal isOpen={!!rejectModal} onClose={() => setRejectModal(null)} title="Reject Registration" size="sm">
        <div className="p-5 space-y-4">
          <p className="text-sm text-gray-400">Reject {rejectModal?.user?.name}'s registration request?</p>
          <div className="space-y-1.5">
            <label className="label">Rejection Reason *</label>
            <textarea value={rejectReason} onChange={e => setRejectReason(e.target.value)} className="input-field min-h-[80px] resize-none" placeholder="Please provide a reason..." />
          </div>
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setRejectModal(null)}>Cancel</Button>
            <Button variant="danger" onClick={handleReject}><XCircle size={14} /> Reject</Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

